body.sysmlSnippet:
part def BatteryElectricVehicle {
  part tractionBatteryPack;
  part electricTractionMotor;
  part chargePort;
}

part def TractionBatteryPack {
  port dcPower;
  attribute stateOfCharge;
}

part def BatteryManagementSystem {
  port sensorInputs;
  port controlOutputs;
}

part def ElectricTractionMotor {
  port electricalPower;
  port mechanicalTorque;
}

part def PowerElectronicsController {
  port dcInput;
  port motorDriveOutput;
}

part def DCDCConverter {
  port highVoltageInput;
  port lowVoltageOutput;
}

part def ChargingSubsystem {
  part chargePort;
  part onboardCharger;
}

requirement thermalEfficiency;
requirement cabinComfort;
requirement batteryReliability;

part def HVACSystem;
requirement cabinComfort;
requirement drivingRange;
